WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_interval_base'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '间隔基期', 'kp-xingce-data-interval-base', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "间隔基期"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "跨越一个中间年份的基期倒推计算，必须融合间隔增长率。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目给出2023年的数据以及2023、2022两年的增长率，突然问你2021年（隔了一年）的具体数值是多少。特征：年份跨度为2年。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "分两步走，先求间隔增长率 R，再求基期："}]}, {"type": "katexBlock", "attrs": {"content": "R = r_1 + r_2 + r_1 \\times r_2 \\quad \\Rightarrow \\quad 间隔基期量 = \\frac{现期量}{1 + R}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[圈出年份发现跨越了一年] --> B[搜集近两年的增长率 r1 和 r2]\nB --> C[利用公式计算出间隔增长率 R]\nC --> D[列出基期式子: 现期量 / (1+R)]\nD --> E[使用截位直除法计算最终结果]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某省产值 5432 亿元，同比增长 10%，2022年同比增长 20%。问 2021 年产值多少？选项：A. 3850 B. 4115 C. 4520 D. 4930"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别考点：求两年前的量，为间隔基期。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一步求 R：R = 10% + 20% + 10% × 20% = 30% + 2% = 32%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二步求基期：2021年基期量 = 5432 / (1 + 32%) = 5432 / 1.32。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第三步直除：5432 ÷ 1.32，商首位是 4，第二位是 1。序列约 41...。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B (4115)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "绝命大坑：连续做两次除法！", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些考生喜欢列式：5432 ÷ (1+10%) ÷ (1+20%)。这种连续做两次除法的式子在考场上极其耗时，且极易算错。必须老老实实把 R 算出来，只做一次除法！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "训练自己遇到跨年题第一时间反应出“算R公式”。熟练掌握 r1×r2 尾项的快速心算法。"}]}]}$$ AS jsonb), NULL, '间隔基期的核心考点与实战推导。', category_node.id, CAST('["资料分析", "间隔基期"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_interval_base", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
